S=$(mktemp -d) && mkdir -p $S/caruca/ir && touch $S/caruca/__init__.py $S/caruca/ir/__init__.py && cat > $S/caruca/ir/syntax.py <<'EOF'
import enum
class Arity(enum.Enum):
    OPTIONAL=1; ZERO_OR_ONE=1; EXACTLY_ONE=2; EXACTLY_TWO=3; ZERO_OR_MORE=4; AT_LEAST_ONE=5; ONE_OR_MORE=5
SyntaxSpecification=list
class Node:
    def __init__(self, flag=None, alias=(), arity=Arity.OPTIONAL, **kw):
        self.flag=flag; self.alias=list(alias); self.arity=arity; self.kw=kw; self.kind=type(self).__name__
class Flag(Node):
    def __init__(self, flag, alias=(), **kw): super().__init__(flag, alias, **kw)
for n in "Path Integer Int Number Pid Duration String Other User Format Selection List Regex Glob Separator Delimiter Char Range Size Permission OwnerGroup Group Signal Variable Command Hostname Filesystem Date DateTime DateFormat TimeStyle Expression PrintfFormat SprintfFormat Geometry SecurityContext SecurityRange SecurityRole SecurityType".split():
    globals()[n]=type(n,(Node,),{})
EOF
PYTHONPATH=$S:output python3 - <<'EOF'
import json, binwalk as bw_spec_mod  # noqa
from binwalk import binwalk_syntax_spec as spec
import importlib, sys
sys.path.insert(0,'/usr/lib/python3/dist-packages')
import binwalk.core.module as M
real = {}
for m in M.Modules().list(attribute="CLI"):
    for o in m.CLI:
        if o.long and not o.hidden: real[o.short]=(o.long, o.type)
opts, pos = spec[0]
ok=True
seen=set()
for n in opts:
    s=n.flag[1:]; seen.add(s)
    if s not in real: print("EXTRA in spec:", n.flag); ok=False; continue
    long_, t = real[s]
    if n.alias != ["--"+long_]: print("alias mismatch", n.flag, n.alias, long_); ok=False
    if (t is None) != (n.kind=="Flag"): print("flag/value mismatch", n.flag, t, n.kind); ok=False
    rep = (t is list); spec_rep = n.arity==Arity.ZERO_OR_MORE if False else n.arity.name=="ZERO_OR_MORE"
    if rep != spec_rep: print("arity mismatch", n.flag, t, n.arity); ok=False
    if t is int and n.kind!="Integer": print("int type mismatch", n.flag, n.kind); ok=False
for s,(l,t) in real.items():
    if s not in seen: print("MISSING from spec:", s, l); ok=False
print("syntax spec vs binary:", "OK" if ok else "MISMATCH", "| options:", len(opts), "| positional:", [(p.kind,p.arity.name) for p in pos])
# JSON check
d=json.load(open('output/pash/binwalk.json'))
jf={e[0] if isinstance(e,list) else e: e for e in d['flag']}; jo={e[0]: e for e in d['option']}
ok=True
for s,(l,t) in real.items():
    key="-"+s
    if t is None:
        if key not in jf or jf[key]!=[key,"--"+l]: print("JSON flag problem", key, jf.get(key)); ok=False
    else:
        if key not in jo or jo[key][:2]!=[key,"--"+l]: print("JSON option problem", key, jo.get(key)); ok=False
for k in list(jf)+list(jo):
    if k[1:] not in real: print("JSON extra", k); ok=False
print("json vs binary:", "OK" if ok else "MISMATCH")
EOF
cat > $S/Arity_fix.txt </dev/null

